def sort_age(lst):
    n = len(lst)
    result = []
    while n != 0:
        test = []
        for counter in range(n):
            test.append(lst[counter][1])
        first = max(test)
        for counter in range(n):
            if counter == len(lst):
                break
            elif lst[counter][1] == first:
                result.append(lst.pop(counter))
        n = len(lst)
    return result

